GLOSSARY = {
 "wakefulness": ("Wakefulness","The state of being alert and responsive, as opposed to deep sleep or coma. It is one of several senses of 'conscious' and can come apart from having experiences, as in dreaming."),
 "phenomenal": ("Phenomenal consciousness","The felt, experiential side of mental life: what it is like to see red or feel pain. Used in contrast with access consciousness by Ned Block."),
 "access": ("Access consciousness","Information that is available for reasoning, report and the control of action. Block proposed it as distinct from phenomenal consciousness; whether they can be separated is debated."),
 "perception": ("Perception","The process by which the brain turns signals from the senses into an interpretation of the world, using expectation as well as input."),
 "predictive": ("Predictive processing","A family of ideas in which the brain continually predicts its sensory input and updates the predictions when they are wrong. It is a framework under discussion, not a settled account."),
 "contrastive": ("Contrastive method","Comparing brain activity when the same stimulus is and is not consciously perceived, to look for activity linked to experience."),
 "attention": ("Attention","The selection of some information for fuller processing at the expense of other information. Related to, but distinguished by many researchers from, awareness."),
 "ncc": ("Neural correlate of consciousness","A pattern of brain activity that accompanies a particular conscious experience. The term does not claim the activity produces the experience.","theory"),
 "gnwt": ("Global Neuronal Workspace Theory","A theory proposing that a representation becomes consciously accessible when it is amplified and made available to many specialised processes through a distributed network.","theory:gnwt"),
 "iit": ("Integrated Information Theory","A theory deriving consciousness from properties of experience such as unity and proposing that it corresponds to the cause-effect structure of a physical system.","theory:iit"),
 "hot": ("Higher-Order Theories","Theories holding that a mental state is conscious when the subject has a higher-order representation of being in that state.","theory:hot"),
 "rpt": ("Recurrent Processing Theory","A theory associating consciousness with feedback processing in sensory areas rather than the first feedforward sweep.","theory:rpt"),
 "ast": ("Attention Schema Theory","A theory proposing that subjective awareness is the brain's simplified model of its own attention.","theory:ast"),
 "pp": ("Predictive Processing and consciousness","Approaches applying the predictive processing framework to questions about consciousness.","theory:pp"),
 "parameters": ("Parameters","The adjustable numbers in a model whose values are set by training."),
 "supervised": ("Supervised learning","Learning from examples that come with the right answers."),
 "unsupervised": ("Unsupervised learning","Looking for structure in data without labels."),
 "rl": ("Reinforcement learning","Learning which actions lead to better outcomes from rewards and penalties received after acting."),
 "overfitting": ("Overfitting","When a model matches its training data so closely, including noise, that it performs worse on new data."),
 "generalisation": ("Generalisation","How well a model performs on data it has not seen during training."),
 "testset": ("Test set","Data held back from training and used to measure how well a model generalises."),
 "neuralnet": ("Neural network","A model made of simple units with adjustable weights, arranged in layers. 'Neural' reflects early inspiration from the brain; it is not a model of real neurons."),
 "lm": ("Language model","A model that assigns probabilities to what text is likely to come next, used to generate and process text."),
 "tokens": ("Tokens","The pieces of text, often words or parts of words, that a language model reads and predicts."),
 "benchmark": ("Benchmark","A standard set of tasks with agreed scoring used to compare systems."),
}
